const S={demo:new URLSearchParams(location.search).has('demo'),user:null,view:'project',projects:[],data:null,chatDrafts:{},demoRooms:{},filter:'all',a:null,b:null,notifications:[],unread:{total:0,chat:0,projects:0},authRole:'client',config:{},storage:null,audioReady:false,replyTo:null};
