function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
async function api(path,body,method){const r=await apiFetch(path,{method:method||(body?'POST':'GET'),credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(d.token)saveSession(d.token);if(!r.ok){if(r.status===401&&S.user){saveSession(null);stopRealtime();audio.close();buffers.clear();S.user=null;S.data=null;S.projects=[];S.notifications=[];S.chatDrafts={};renderAuth();}throw Error(d.error||'연결을 확인해 주세요.');}return d;}
const projectPath=()=>'/projects/'+S.data.project.id;
function modal(title,html){const d=$('#modal');d.innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="ghost icon-btn" data-action="close-modal" aria-label="닫기">${icon('close')}</button></div><div class="modal-body">${html}</div>`;if(!d.open)d.showModal();}
function closeModal(){$('#modal').close();$('#modal').innerHTML='';}
function empty(text){return `<div class="empty">${icon('headphones')}<p>${esc(text)}</p></div>`;}
function demoData(){const now=Date.now(),pid='demo-project';S.user={role:'engineer',name:'관리자',projectId:null};const p={id:pid,title:'프로젝트 01',client_name:'고객',description:'',status:'active',created_at:now-5*86400000,updated_at:now};S.projects=[p];S.data={project:p,versions:[{id:'v3',number:3,label:'3차 수정본',file_name:'Project_Mix_03.wav',bytes:34700000,duration:92,note:'보컬·공간감 수정',created_at:now-3600000},{id:'v2',number:2,label:'2차 수정본',file_name:'Project_Mix_02.wav',bytes:34700000,duration:92,note:'저역 수정',created_at:now-86400000},{id:'v1',number:1,label:'1차 믹스',file_name:'Project_Mix_01.wav',bytes:34700000,duration:92,note:'',created_at:now-3*86400000}],requests:[{id:'r1',version_id:'v2',start:42,end:56,text:'후렴 보컬 볼륨을 조금 높여 주세요.',status:'resolved',resolved_version_id:'v3',created_at:now-8000000},{id:'r2',version_id:'v2',start:65,end:78,text:'마지막 후렴의 공간감을 넓혀 주세요.',status:'working',created_at:now-9000000},{id:'r3',version_id:'v1',start:12,end:24,text:'도입부 저역을 정리해 주세요.',status:'confirmed',resolved_version_id:'v2',created_at:now-3*86400000}],messages:[{id:'m1',role:'engineer',text:'3차 수정본 업로드했습니다.',created_at:now-3600000},{id:'m2',role:'client',text:'확인 후 의견 남기겠습니다.',created_at:now-3000000}]};S.a='v2';S.b='v3';S.data.project.client_name='고객 01';S.demoRooms={'demo-project':S.data};
  for(let number=2;number<=3;number++){
    const room=structuredClone(S.data),id='demo-project-'+number;
    room.project={...room.project,id,title:'프로젝트 0'+number,client_name:'고객 0'+number,status:number===3?'completed':'active'};
    room.versions.forEach(v=>{v.id=id+'-v'+v.number;});
    room.requests=room.requests.slice(0,1).map(r=>({...r,id:id+'-r1',version_id:id+'-'+r.version_id,resolved_version_id:id+'-'+r.resolved_version_id}));
    room.messages=room.messages.map(m=>({...m,id:id+'-'+m.id}));S.demoRooms[id]=room;S.projects.push(room.project);
  }
  S.notifications=[
    {id:'demo-request',recipient:'engineer',project_id:pid,type:'request',title:'새 수정 요청이 도착했어요.',target_id:'r2'},
    {id:'demo-chat-1',recipient:'engineer',project_id:pid,type:'message',title:'새 메시지가 도착했어요.',target_id:null},
    {id:'demo-chat-2',recipient:'engineer',project_id:pid+'-2',type:'message',title:'새 메시지가 도착했어요.',target_id:null},
    {id:'demo-version',recipient:'client:'+pid,project_id:pid,type:'version',title:'새 수정본이 도착했어요.',target_id:'v3'},
    {id:'demo-reply',recipient:'client:'+pid,project_id:pid,type:'message',title:'수정 요청에 답변이 도착했어요.',target_id:'r1'}
  ].map((n,i)=>({...n,project_title:S.demoRooms[n.project_id].project.title,created_at:now-i*60000,read_at:null}));
  S.demoRooms[pid].messages.push({id:'demo-reply-message',role:'engineer',request_id:'r1',text:'3차 수정본에 반영했어요. 같은 구간에서 비교해 주세요.',created_at:now-60000});
}
const noteRecipient=()=>S.user?.role==='engineer'?'engineer':'client:'+S.user?.projectId;
const visibleNotes=()=>S.demo?S.notifications.filter(n=>n.recipient===noteRecipient()):S.notifications;
function unreadCounts(){
  if(!S.demo)return S.unread;
  const notes=visibleNotes().filter(n=>!n.read_at);
  return {total:notes.length,chat:notes.filter(n=>n.type==='message'&&!n.target_id).length,projects:notes.filter(n=>['request','version','status'].includes(n.type)||(n.type==='message'&&n.target_id)).length};
}
function menuIcon(name,group){return '<span class="menu-icon">'+icon(name)+'<span class="unread-badge" data-unread="'+group+'" aria-hidden="true" hidden></span></span>';}
function updateNotificationBadges(){
  const counts=unreadCounts(),labels={total:'알림함',chat:'채팅',projects:'프로젝트'};
  document.querySelectorAll('[data-unread]').forEach(b=>{
    const count=counts[b.dataset.unread]||0;b.textContent=count>99?'99+':String(count);b.hidden=!count;
    b.closest('button')?.setAttribute('aria-label',labels[b.dataset.unread]+(count?', 읽지 않은 알림 '+count+'개':''));
  });
}
async function refreshNotifications(){
  if(!S.demo){const data=await api('/notifications');S.notifications=data.notifications;S.unread=data.unread;}
  updateNotificationBadges();
  if(S.view==='notifications'&&$('#content'))renderNotifications();
}
async function readNotifications(selection){
  if(S.demo){
    visibleNotes().filter(n=>!n.read_at&&(selection.all||n.id===selection.id||(selection.projectId===n.project_id&&n.type==='message'&&!n.target_id&&n.created_at<=selection.through))).forEach(n=>n.read_at=Date.now());
  }else await api('/notifications/read',selection);
  await refreshNotifications();
}
async function readCurrentChat(){
  if(!S.data||S.view!=='chat')return;
  await readNotifications({projectId:S.data.project.id,kind:'chat',through:S.demo?Date.now():S.data.notificationCutoff});
}
function focusNotificationTarget(selector){
  document.querySelectorAll('.notification-target').forEach(e=>e.classList.remove('notification-target'));
  const el=$(selector);if(!el)return;
  el.classList.add('notification-target');el.focus({preventScroll:true});el.scrollIntoView({block:'center'});
}
async function openNotification(id){
  const n=visibleNotes().find(n=>n.id===id)||(!S.demo?(await api('/notifications/'+encodeURIComponent(id))).notification:null);
  if(!n)throw Error('알림을 찾을 수 없어요.');
  S.filter='all';
  await openProject(n.project_id,n.type==='message'&&!n.target_id?'chat':'project');
  if(n.type==='request'||(n.type==='message'&&n.target_id)){
    const r=S.data.requests.find(r=>r.id===n.target_id);
    if(!r)throw Error('이 수정 요청은 삭제되었어요.');
    S.a=r.version_id;S.b=r.resolved_version_id||S.data.versions[0]?.id;
    if($('#version-A')&&S.a&&S.b&&S.data.versions.some(v=>v.id===S.a)){
      $('#version-A').value=S.a;$('#version-B').value=S.b;await loadAudio();
      if(S.audioReady){
        if(r.end>audio.duration()){S.b=S.a;$('#version-B').value=S.b;await loadAudio();}
        await audio.setRange(r.start,r.end);await audio.setLoop(true);await audio.seek(r.start);syncRange();
        $('[data-action="loop"]').classList.add('loop-active');$('[data-action="loop"]').setAttribute('aria-pressed','true');
      }
    }
    focusNotificationTarget('[data-request-id="'+CSS.escape(r.id)+'"]');
    if(n.type==='message')replyModal(r.id);
  }else if(n.type==='version'){
    const v=S.data.versions.find(v=>v.id===n.target_id);
    if(!v)throw Error('이 음원 버전은 삭제되었어요.');
    S.b=v.id;S.a=S.data.versions.find(other=>other.number<v.number)?.id||v.id;
    $('#version-A').value=S.a;$('#version-B').value=S.b;await loadAudio();
    focusNotificationTarget('[data-version-id="'+CSS.escape(v.id)+'"]');
  }
  if(!n.read_at)await readNotifications({id:n.id});
}
const visibleProjects=()=>S.user?.role==='client'?S.projects.filter(p=>p.id===S.user.projectId):S.projects;
function themeButton(){return '<button type="button" class="ghost icon-btn" data-theme-toggle aria-label="테마 전환"></button>';}
function themeChoices(){return '<section class="settings-card"><h2>화면 테마</h2><div class="theme-options" role="group" aria-label="화면 테마"><button data-set-theme="light">라이트</button><button data-set-theme="dark">다크</button><button data-set-theme="system">기기 설정</button></div></section>';}
function renderAuth(error=''){
  $('#app').innerHTML='<main class="entry-page"><header class="entry-top"><a class="brand" href="./">'+brand+'</a>'+themeButton()+'</header><section class="entry-card">'+
    (S.demo?'<span class="entry-preview">미리보기</span>':'')+'<img class="entry-icon" src="./icon.svg" alt=""><h1>프로젝트 입장</h1><div class="segment" aria-label="입장 역할"><button data-action="auth-role" data-role="client" class="'+(S.authRole==='client'?'active':'')+'">고객</button><button data-action="auth-role" data-role="engineer" class="'+(S.authRole==='engineer'?'active':'')+'">관리자</button></div><form id="login-form">'+
    (S.authRole==='client'?'<label>접속 코드<input name="code" required autocomplete="off" placeholder="전달받은 코드를 입력하세요" '+(S.demo?'value="MIXROOM-DEMO" readonly':'')+'></label>':'<label>관리자 비밀번호<input name="password" type="password" required autocomplete="'+(S.demo?'off':'current-password')+'" '+(S.demo?'value="demo-preview" readonly':'placeholder="비밀번호를 입력하세요"')+'></label>')+
    '<p class="error" id="auth-error">'+esc(error)+'</p><button class="primary entry-submit">입장 '+icon('chevron')+'</button></form><div class="entry-links"><button class="ghost" data-action="auth-guide">사용 가이드</button>'+(!S.demo?'<a href="./?demo=1">미리보기</a>':'')+'</div>'+(!S.demo&&S.config.setup?'<button class="ghost entry-setup" data-action="setup">관리자 계정 만들기</button>':'')+'</section></main>';
  window.MixroomTheme?.sync();
}
function render(){if(!S.user){renderAuth();return;}const engineer=S.user.role==='engineer';$('#app').innerHTML=`<div class="shell ${S.view==='chat'?'chat-view':''}"><aside class="sidebar"><a class="brand" href="./">${brand}</a><div class="side-label"></div><nav><button class="nav ${['project','projects'].includes(S.view)?'active':''}" data-action="view" data-view="projects">${menuIcon('grid','projects')}<span>프로젝트</span></button><button class="nav ${S.view==='chat'?'active':''}" data-action="view" data-view="chat">${menuIcon('chat','chat')}<span>채팅</span></button>${engineer?`<button class="nav ${S.view==='customers'?'active':''}" data-action="view" data-view="customers">${icon('users')}<span>고객 관리</span></button>`:''}<button class="nav ${S.view==='notifications'?'active':''}" data-action="view" data-view="notifications">${menuIcon('bell','total')}<span>알림함</span></button><button class="nav ${S.view==='guide'?'active':''}" data-action="view" data-view="guide">${icon('book')}<span>사용 가이드</span></button><button class="nav ${S.view==='settings'?'active':''}" data-action="view" data-view="settings">${icon('settings')}<span>설정</span></button></nav><div class="side-footer"><button class="nav" data-action="logout">${icon('logout')} 로그아웃</button><div class="profile"><span class="avatar">${esc(S.user.name.slice(0,1))}</span><div><strong>${esc(S.user.name)}</strong><small>${engineer?'관리자':'고객'}</small></div></div></div></aside><main class="main">${S.demo?`<div class="notice-banner">미리보기 <button data-action="entry-preview">입장 화면</button><button data-action="demo-role">${engineer?'고객 화면':'관리자 화면'}</button></div>`:''}<header class="topbar"><div class="crumbs">MIXROOM ${icon('chevron')} <strong>${S.view==='project'?esc(S.data?.project.title||'프로젝트'):({projects:'프로젝트',customers:'고객 관리',chat:'채팅',notifications:'알림함',guide:'사용 가이드',settings:'설정'}[S.view])}</strong></div><a class="brand mobile-brand" href="./">${brand}</a><div class="row">${themeButton()}<button class="ghost top-guide" data-action="view" data-view="guide" style="font-size:11px">${icon('book')} 사용 가이드</button><button class="ghost icon-btn" data-action="view" data-view="notifications" aria-label="알림함">${menuIcon('bell','total')}</button><span class="avatar">${esc(S.user.name.slice(0,1))}</span></div></header><div class="content" id="content"></div></main></div>`;renderContent();updateNotificationBadges();window.MixroomTheme?.sync();}
function heading(eyebrow,title,description,actions=''){return '<div class="page-heading"><div>'+ (eyebrow?'<div class="eyebrow" style="margin-bottom:10px">'+esc(eyebrow)+'</div>':'')+'<h1>'+esc(title)+'</h1>'+(description?'<p>'+esc(description)+'</p>':'')+'</div>'+(actions?'<div>'+actions+'</div>':'')+'</div>';}
function renderContent(){const c=$('#content');if(S.view==='project'&&S.data){c.innerHTML=workspace();bindWaves();loadAudio();}else if(S.view==='projects'){c.innerHTML=heading('','프로젝트','',S.user.role==='engineer'?`<button class="primary" data-action="new-project">${icon('plus')} 새 프로젝트</button>`:'')+`<div class="project-grid">${visibleProjects().map(p=>`<button class="project-card" data-action="open-project" data-id="${p.id}"><span class="pill ${p.status==='active'?'green':'gray'}"><span class="dot"></span>${{active:'진행 중',completed:'작업 완료',archived:'접속 종료'}[p.status]}</span><h2>${esc(p.title)}</h2><p>${esc(p.description||'')}<br>${esc(p.client_name||'고객 정보 삭제됨')}</p><footer><span>${date(p.updated_at)}</span><span>작업실 열기 ↗</span></footer></button>`).join('')}</div>${!visibleProjects().length?empty('첫 프로젝트를 만들고 고객을 초대해 보세요.'):''}`;}else if(S.view==='customers'){c.innerHTML=customersWorkspace();}else if(S.view==='chat'){c.innerHTML=chatWorkspace();updateChat(true);}else if(S.view==='notifications')renderNotifications();else if(S.view==='guide')c.innerHTML=guideHTML(S.user.role);else if(S.view==='settings')c.innerHTML=settings();window.MixroomTheme?.sync();}
function options(selected){return S.data.versions.map(v=>`<option value="${v.id}" ${v.id===selected?'selected':''}>v${v.number} · ${esc(v.label)}</option>`).join('');}
function track(key,selected){return `<div class="track ${audio.selected===key?'selected':''}" id="track-${key}"><div class="track-top"><span class="track-letter">${key}</span><select id="version-${key}" aria-label="${key} 버전 선택">${options(selected)}</select><small style="margin-left:auto">${key==='A'?'이전 버전':'수정 버전'}</small></div><div class="wave-wrap" data-wave="${key}" aria-label="${key} 음원 파형. 드래그하면 반복 구간을 선택합니다." role="slider" tabindex="0" aria-valuemin="0" aria-valuemax="${audio.duration()}" aria-valuenow="0"><canvas class="wave" id="wave-${key}"></canvas><div class="wave-selection"></div><div class="playhead"></div></div><div class="wave-times"><span>00:00</span><span class="wave-duration">${fmt(S.data.versions.find(v=>v.id===selected)?.duration)}</span></div></div>`;}
function workspace(){const {project:p,versions}=S.data,engineer=S.user.role==='engineer';return heading('',p.title,'',`<div class="row"><span class="pill ${p.status==='active'?'green':'gray'}"><span class="dot"></span>${{active:'진행 중',completed:'작업 완료',archived:'접속 종료'}[p.status]}</span>${engineer&&p.status==='active'?`<button data-action="invite">${icon('link')} 초대</button><button class="primary" data-action="upload">${icon('upload')} 새 버전</button>`:''}</div>`)+`${p.status!=='active'?'<div class="pending">'+(p.status==='completed'?'작업이 완료되었어요. 음원을 비교하고 최종본을 다운로드할 수 있어요.':'고객 접속이 종료되고 대화와 고객 정보가 삭제된 프로젝트예요.')+'</div>':''}<div class="workspace"><section><div class="player"><div class="player-top row between"><h2>음원 비교</h2>${icon('headphones')}</div>${versions.length?`<div class="version-compare">${track('A',S.a)}${track('B',S.b)}</div><p class="player-hint" id="audio-hint">음원을 불러오는 중이에요.</p><div class="transport"><button class="play primary" data-action="play" aria-label="재생" id="play-button" disabled>${icon('play')}</button><div class="time"><strong id="time-current">00:00</strong> <span>/ <span id="time-total">${fmt(versions[0].duration)}</span></span></div><div class="segment" aria-label="비교 버전"><button data-action="ab" data-key="A" class="${audio.selected==='A'?'active':''}">A</button><button data-action="ab" data-key="B" class="${audio.selected==='B'?'active':''}">B</button></div><button class="icon-btn ${audio.loop?'loop-active':''}" data-action="loop" aria-label="구간 반복" aria-pressed="${audio.loop}">${icon('loop')}</button><div class="row volume-wrap" style="margin-left:auto;color:#b2a6bf">${icon('volume')}<input id="volume" class="volume" type="range" min="0" max="1" step="0.01" value="${audio.volume}" aria-label="볼륨"></div><span class="kbd">Space</span></div><div class="range-controls"><span style="color:#8f72b6">${icon('loop')} 반복 구간</span><label><span class="sr-only">시작(초)</span><input id="range-start" type="number" min="0" step="0.1" value="0" aria-label="반복 시작 초"></label><span>—</span><label><span class="sr-only">끝(초)</span><input id="range-end" type="number" min="0" step="0.1" value="12" aria-label="반복 끝 초"></label><span class="separator"></span><label class="offset-control">B 위치 보정 <input id="offset" type="number" min="-10" max="10" step="0.01" value="0" aria-label="B 버전 시간 보정 초"> 초</label></div>`:empty('첫 믹스를 올리면 비교가 시작돼요.')}</div>${requestComposer()}<div class="section-heading"><h2>버전 히스토리 <span style="margin-left:8px">${versions.length}</span></h2></div><div class="history">${versions.length?versions.map((v,i)=>`<div class="history-row" data-version-id="${v.id}" tabindex="-1"><span class="version-icon">v${v.number}</span><div class="grow"><h3>${esc(v.label)} ${i===0?'<span class="pill" style="padding:2px 5px;font-size:8px;margin-left:4px">최신</span>':''}</h3><p>${date(v.created_at)} · ${(v.bytes/1024/1024).toFixed(1)} MB</p></div><div class="note">${esc(v.note)}</div><button class="ghost icon-btn" data-action="download" data-id="${v.id}" aria-label="v${v.number} 원본 다운로드">${icon('download')}</button>${engineer?`<button class="ghost icon-btn danger" data-action="delete-audio" data-id="${v.id}" aria-label="v${v.number} 음원 삭제">${icon('close')}</button>`:''}</div>`).join(''):empty('아직 업로드된 음원이 없어요.')}</div></section><aside><div class="review-panel"><div class="review-heading"><h2>수정 요청 <span class="tab-count">${S.data.requests.length}</span></h2><button class="ghost" data-action="view" data-view="chat">${icon('chat')} 채팅</button></div><div id="review-content">${review()}</div></div></aside></div>`;}
function review(){const engineer=S.user.role==='engineer',active=S.data.project.status==='active';  const requests=S.data.requests.filter(r=>S.filter==='all'||(S.filter==='pending'?['open','working'].includes(r.status):['resolved','confirmed'].includes(r.status)));return `<div class="panel-body"><div class="filter-row"><button data-action="filter" data-filter="all" class="${S.filter==='all'?'active':''}">전체</button><button data-action="filter" data-filter="pending" class="${S.filter==='pending'?'active':''}">진행 중</button><button data-action="filter" data-filter="done" class="${S.filter==='done'?'active':''}">반영·확인</button></div>${requests.map(r=>`<article class="request-card" data-request-id="${r.id}" tabindex="-1"><div class="row between"><button class="timestamp" data-action="request-play" data-id="${r.id}" ${S.data.versions.some(v=>v.id===r.version_id)?'':'disabled title="원본 음원이 삭제되었어요"'}>${icon('play')} ${fmt(r.start)} — ${fmt(r.end)}</button><span class="pill ${r.status==='confirmed'?'green':r.status==='working'?'amber':r.status==='open'?'gray':''}">${statusLabel[r.status]}</span></div><p>${esc(r.text)}</p><div class="byline"><span class="avatar">${esc((S.data.project.client_name||'고객')[0])}</span>${esc(S.data.project.client_name||'고객')}<span>· v${S.data.versions.find(v=>v.id===r.version_id)?.number||'삭제됨'}</span><span style="margin-left:auto">${date(r.created_at).split(' ').slice(0,4).join(' ')}</span></div><div class="request-foot" style="margin-top:12px"><button class="ghost" data-action="reply" data-id="${r.id}">${icon('chat')} 답변 ${S.data.messages.filter(m=>m.request_id===r.id).length||''}</button>${active?(engineer?`<select class="status-select" data-request="${r.id}" aria-label="요청 상태"><option value="" selected>상태 변경</option value="open">접수</option><option value="working">작업 중</option><option value="resolved">반영 완료</option></select>`:r.status==='resolved'?`<button class="accent" data-action="confirm-request" data-id="${r.id}">수정 확인했어요</button>`:r.status==='confirmed'?`<button data-action="reopen-request" data-id="${r.id}">다시 요청</button>`:''):''}</div></article>`).join('')||empty('아직 수정 요청이 없어요.')}</div>`;}
function requestComposer(){
  if(S.user.role!=='client'||S.data.project.status!=='active'||!S.data.versions.length)return '';
  return '<section class="request-compose-card"><h2>수정 요청 남기기</h2><form id="request-form" class="compose"><div class="row between"><span class="timestamp" id="comment-range">'+fmt(audio.range.start)+' — '+fmt(audio.range.end)+'</span><button type="button" class="ghost" data-action="mark-time">현재 위치 사용</button></div><textarea name="text" required maxlength="2000" placeholder="수정할 내용을 입력하세요" aria-label="수정 요청 내용"></textarea><div class="row between"><p id="comment-version">'+audio.selected+' 버전에 남겨요.</p><button class="primary">수정 요청 남기기</button></div></form></section>';
}
function customersWorkspace(){
  if(S.user.role!=='engineer')return '';
  const customers=S.projects.filter(p=>p.status!=='archived');
  return heading('','고객 관리','', '<button class="primary" data-action="new-project">'+icon('plus')+' 고객 추가</button>')+'<div class="customer-list">'+customers.map(p=>'<article class="customer-row"><div class="customer-person"><span class="avatar">'+esc((p.client_name||'고객')[0])+'</span><div><h2>'+esc(p.client_name||'고객')+'</h2><p>'+esc(p.title)+'</p></div></div><span class="pill '+(p.status==='active'?'green':'gray')+'">'+(p.status==='active'?'진행 중':'작업 완료')+'</span><div class="customer-actions"><button data-action="open-project" data-id="'+esc(p.id)+'">'+icon('headphones')+' 프로젝트</button><button data-action="open-chat" data-id="'+esc(p.id)+'">'+icon('chat')+' 채팅</button><button data-action="customer-manage" data-id="'+esc(p.id)+'">'+icon('settings')+' 관리</button></div></article>').join('')+'</div>'+(!customers.length?empty('등록된 고객이 없어요.'):'');
}
async function customerManage(id){
  if(S.user.role!=='engineer')return;
  audio.close();audioGeneration++;S.data=S.demo?S.demoRooms[id]:await api('/projects/'+id);const p=S.data.project;
  modal(p.client_name||'고객 관리','<p>'+esc(p.title)+'</p><div class="customer-management"><button data-action="invite">'+icon('link')+' 접속 코드 재발급</button><button data-action="project-status">'+icon('check')+' '+(p.status==='active'?'작업 완료로 변경':'프로젝트 다시 열기')+'</button><button class="danger" data-action="close-project">'+icon('close')+' 고객 삭제</button></div>');
}
function messageHTML(m){return `<div class="message ${m.role===S.user.role?'mine':''}"><div class="byline">${m.role==='engineer'?'엔지니어':esc(S.data.project.client_name||'고객')}<small style="margin-left:auto">${date(m.created_at)}</small></div><div class="bubble">${esc(m.text)}</div></div>`;}
function updateReview(){const el=$('#review-content');if(!el)return;const draft=$('#request-form textarea')?.value;el.innerHTML=review();const textarea=el.querySelector('textarea');if(textarea&&draft)textarea.value=draft;$('.tab-count').textContent=S.data.requests.length;}
function tick(t){if(!$('#time-current'))return;$('#time-current').textContent=fmt(t);$('#time-total').textContent=fmt(audio.duration());document.querySelectorAll('.playhead').forEach(e=>e.style.left=(audio.duration()?100*t/audio.duration():0)+'%');document.querySelectorAll('.wave-wrap').forEach(e=>e.setAttribute('aria-valuenow',String(Math.round(t))));const b=$('#play-button');if(b){b.innerHTML=icon(audio.playing?'pause':'play');b.setAttribute('aria-label',audio.playing?'일시정지':'재생');}}
function syncRange(){const d=audio.duration()||1;for(const e of document.querySelectorAll('.wave-selection')){e.style.left=100*audio.range.start/d+'%';e.style.width=100*(audio.range.end-audio.range.start)/d+'%';}if($('#range-start'))$('#range-start').value=audio.range.start.toFixed(1);if($('#range-end'))$('#range-end').value=audio.range.end.toFixed(1);if($('#comment-range'))$('#comment-range').textContent=fmt(audio.range.start)+' — '+fmt(audio.range.end);}
function drawWaves(){for(const key of ['A','B']){const c=$('#wave-'+key),buffer=audio.buffers[key];if(!c||!buffer)continue;const width=c.clientWidth,height=c.clientHeight,dpr=devicePixelRatio||1;c.width=width*dpr;c.height=height*dpr;const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const values=peaks(buffer,Math.max(100,Math.floor(width/3))),max=Math.max(...values,.05);const colors=getComputedStyle(document.documentElement);ctx.fillStyle=colors.getPropertyValue(key===audio.selected?'--wave-active':'--wave-idle').trim();values.forEach((v,i)=>{const h=Math.max(2,v/max*(height-10));ctx.fillRect(i*width/values.length,(height-h)/2,Math.max(1,width/values.length-1),h);});}syncRange();}
async function loadAudio(){if(!S.data?.versions.length){audio.close();buffers.clear();S.audioReady=false;return;}const gen=++audioGeneration;S.audioReady=false;if($('#play-button'))$('#play-button').disabled=true;try{const get=async id=>{if(buffers.has(id))return buffers.get(id);let b;if(S.demo)b=demoBuffer(audio.context(),S.data.versions.find(v=>v.id===id)?.number>=3?2:1);else{const v=S.data.versions.find(v=>v.id===id);const file=await audioFile(projectPath()+'/versions/'+id+'/audio',v.bytes,percent=>{if(gen===audioGeneration&&$('#audio-hint'))$('#audio-hint').textContent=percent+'% 불러오는 중';});b=await audio.decode(await file.arrayBuffer());}buffers.set(id,b);return b;};const a=await get(S.a),b=S.a===S.b?a:await get(S.b);if(gen!==audioGeneration)return;audio.setBuffers(a,b);S.audioReady=true;for(const key of buffers.keys())if(key!==S.a&&key!==S.b)buffers.delete(key);if($('#audio-hint'))$('#audio-hint').textContent=S.a===S.b?'첫 버전':'';if($('#play-button'))$('#play-button').disabled=false;drawWaves();tick(0);syncRange();}catch(e){if(gen===audioGeneration&&$('#audio-hint'))$('#audio-hint').textContent=e.message;}}
function bindWaves(){for(const e of document.querySelectorAll('.wave-wrap')){let start=null;const pos=x=>Math.max(0,Math.min(audio.duration(),(x-e.getBoundingClientRect().left)/e.clientWidth*audio.duration()));e.addEventListener('pointerdown',ev=>{if(!S.audioReady)return;start={x:ev.clientX,t:pos(ev.clientX)};e.setPointerCapture(ev.pointerId);});e.addEventListener('pointermove',ev=>{if(!start||Math.abs(start.x-ev.clientX)<5)return;const t=pos(ev.clientX),a=Math.min(start.t,t),b=Math.max(start.t,t);for(const s of document.querySelectorAll('.wave-selection')){s.style.left=100*a/audio.duration()+'%';s.style.width=100*(b-a)/audio.duration()+'%';}});e.addEventListener('pointerup',async ev=>{if(!start)return;const t=pos(ev.clientX);if(Math.abs(start.x-ev.clientX)<5)await audio.seek(t);else{await audio.setRange(Math.min(start.t,t),Math.max(start.t,t));await audio.setLoop(true);$('[data-action="loop"]').classList.add('loop-active');$('[data-action="loop"]').setAttribute('aria-pressed','true');}start=null;syncRange();});e.addEventListener('keydown',ev=>{if(['ArrowLeft','ArrowRight'].includes(ev.key)){ev.preventDefault();audio.seek(audio.time()+(ev.key==='ArrowLeft'?-1:1));}});}}
async function openProject(id,view='project'){audio.close();S.audioReady=false;audioGeneration++;S.replyTo=null;S.data=S.demo?S.demoRooms[id]:await api('/projects/'+id);S.a=S.data.versions[1]?.id||S.data.versions[0]?.id;S.b=S.data.versions[0]?.id;S.view=view;render();if(view==='chat')await readCurrentChat();}
function chatWorkspace(){
  const rooms=visibleProjects().filter(p=>p.status!=='archived'),p=S.data?.project,selected=p&&p.status!=='archived'?p:null;
  return heading('','채팅','')+'<div class="chat-workspace"><aside class="chat-rooms" aria-label="프로젝트 채팅 목록"><div class="chat-rooms-label"><strong>프로젝트</strong> '+rooms.length+'</div>'+rooms.map(room=>'<button class="chat-room-button '+(room.id===selected?.id?'active':'')+'" data-action="open-chat" data-id="'+esc(room.id)+'" aria-pressed="'+(room.id===selected?.id)+'"><span class="avatar">'+esc((room.client_name||'고객')[0])+'</span><span class="grow"><strong>'+esc(room.title)+'</strong><small>'+esc(room.client_name||'고객')+(room.status==='completed'?' · 완료':'')+'</small></span></button>').join('')+'</aside>'+(selected?'<section class="chat-room"><header class="chat-room-header"><span class="avatar">'+esc((selected.client_name||'고객')[0])+'</span><div class="grow"><h2>'+esc(selected.title)+'</h2><p>'+esc(S.user.role==='engineer'?selected.client_name||'고객':'관리자')+'</p></div><button data-action="open-project" data-id="'+esc(selected.id)+'">'+icon('headphones')+' 음원 비교</button></header><div class="chat-timeline" id="chat-list" role="log" aria-label="프로젝트 메시지" aria-live="polite"></div><div id="chat-composer">'+chatComposer()+'</div></section>':'<div class="chat-empty">'+empty(rooms.length?'프로젝트를 선택하세요.':'프로젝트가 없어요.')+'</div>')+'</div>';
}
function chatComposer(){return S.data.project.status==='active'?'<form id="chat-form" class="chat-compose"><label class="sr-only" for="chat-message">메시지</label><textarea id="chat-message" name="text" required maxlength="2000" placeholder="메시지 입력">'+esc(S.chatDrafts[S.data.project.id]||'')+'</textarea><div class="chat-compose-footer"><p>전송 시 상대방에게 알림</p><button class="primary">'+icon('chat')+' 전송</button></div></form>':'<div class="chat-readonly">완료된 프로젝트 · 읽기 전용</div>';}
function chatMessages(){
  let previous='';
  return S.data.messages.filter(m=>!m.request_id).map(m=>{const day=new Intl.DateTimeFormat('ko-KR',{month:'long',day:'numeric',weekday:'short'}).format(m.created_at);const divider=day!==previous?'<div class="chat-day"><span>'+esc(day)+'</span></div>':'';previous=day;return divider+messageHTML(m);}).join('')||empty('메시지가 없어요.');
}
function updateChat(forceScroll=false){
  const list=$('#chat-list');if(!list)return;
  const nearBottom=list.scrollHeight-list.scrollTop-list.clientHeight<70,scrollTop=list.scrollTop;
  list.innerHTML=chatMessages();list.scrollTop=forceScroll||nearBottom?list.scrollHeight:scrollTop;
  const composer=$('#chat-composer'),active=S.data.project.status==='active';
  if(composer&&active!==!!$('#chat-form'))composer.innerHTML=chatComposer();
}
async function refresh(){if(S.demo||!S.user)return;S.projects=(await api('/projects')).projects;if(S.user.role==='engineer')S.storage=await api('/storage');await refreshNotifications();if(S.data){const d=await api(projectPath());const oldStatus=S.data.project.status,previous=JSON.stringify([S.data.requests,S.data.messages,S.data.project.status]);const versionChanged=JSON.stringify(d.versions.map(v=>v.id))!==JSON.stringify(S.data.versions.map(v=>v.id));S.data=d;if(S.view==='project'){if(oldStatus!==d.project.status){renderContent();}else if(versionChanged){S.a=d.versions[1]?.id||d.versions[0]?.id;S.b=d.versions[0]?.id;renderContent();toast('새 버전이 도착했어요.');}else if(previous!==JSON.stringify([d.requests,d.messages,d.project.status]))updateReview();}else if(S.view==='chat'){if(oldStatus!==d.project.status)renderContent();else if(previous!==JSON.stringify([d.requests,d.messages,d.project.status]))updateChat();}}if(S.view==='chat'){const list=$('#chat-list');if(list&&list.scrollHeight-list.scrollTop-list.clientHeight<70&&visibleNotes().some(n=>!n.read_at&&n.project_id===S.data?.project.id&&n.type==='message'&&!n.target_id))await readCurrentChat();}updateNotificationBadges();}
function renderNotifications(){$('#content').innerHTML=heading('','알림함','','<button data-action="read-notifications">모두 읽음</button>')+`<div class="settings-card">${visibleNotes().map(n=>`<button class="notification-row ${!n.read_at?'unread':''}" data-action="notification" data-id="${n.id}"><span class="dot"></span><div><h3>${esc(n.title)}</h3><p>${esc(n.project_title||S.data?.project.title)} · ${date(n.created_at)}</p></div>${icon('chevron')}</button>`).join('')||empty('아직 새 알림이 없어요.')}</div>`;}
function storageSettings(){return S.user.role==='engineer'&&S.storage?'<section class="settings-card"><h2>음원 저장공간</h2><p>'+Math.ceil(S.storage.bytes/1024/1024)+' MB / '+Math.floor(S.storage.capacity/1024/1024)+' MB</p><p>개별 음원 또는 고객을 삭제하면 저장공간이 확보돼요.</p></section>':'';}
function settings(){const installed=matchMedia('(display-mode: standalone)').matches||navigator.standalone,allowed='Notification'in window&&Notification.permission==='granted';return heading('','설정','')+themeChoices()+storageSettings()+`<section class="settings-card"><h2>이 기기의 앱 알림</h2><p>새 수정본·요청·채팅 알림</p><div class="setting-line"><div><strong style="font-size:12px">알림 권한</strong><p style="margin:5px 0 0">${allowed?'브라우저에서 허용됨 · 서버 연결은 아래에서 확인해 주세요.':'아직 허용하지 않았어요.'}</p></div><span class="pill ${allowed?'green':'gray'}">${allowed?'권한 허용':'설정 필요'}</span></div><div class="row" style="margin-top:15px;flex-wrap:wrap"><button class="accent" data-action="enable-push">${icon('bell')} 알림 켜기</button><button data-action="test-push">테스트 알림</button><button class="ghost" data-action="disable-push">이 기기 알림 끄기</button></div><p id="push-result" style="margin-top:12px;margin-bottom:0" role="status"></p></section><section class="settings-card"><h2>홈 화면에 MIXROOM 추가</h2><p>${installed?'홈 화면에서 앱으로 사용 중이에요.':'아이폰은 Safari에서, 안드로이드는 Chrome에서 설치해 주세요.'}<br>아이폰 알림은 홈 화면에 추가한 앱에서 설정해 주세요.</p><button data-action="view" data-view="guide">${icon('book')} 사진으로 설치·알림 설정 보기</button></section>${S.user.role==='engineer'&&S.data?`<section class="settings-card"><h2>프로젝트 관리 · ${esc(S.data.project.title)}</h2><p>작업 완료 후 고객이 최종본을 받을 시간을 주세요.<br>접속을 종료하면 고객 계정·세션·알림 연결·요청·대화가 삭제돼요.</p><div class="row" style="flex-wrap:wrap">${['active','completed'].includes(S.data.project.status)?`<button data-action="project-status">${S.data.project.status==='active'?'작업 완료로 변경':'프로젝트 다시 열기'}</button><button class="danger" data-action="close-project">고객 접속 종료·정보 삭제</button>`:'<span class="pill gray">접속 종료됨</span>'}</div></section>`:''}<section class="settings-card"><h2>접속 중인 계정</h2><p>${esc(S.user.name)} · ${S.user.role==='engineer'?'엔지니어':'고객'}</p><button data-action="logout">로그아웃</button></section>`;}
function addDemoNotice(type,title,target=null){S.notifications.unshift({recipient:S.user.role==='engineer'?'client:'+S.data.project.id:'engineer',id:crypto.randomUUID(),project_id:S.data.project.id,project_title:S.data.project.title,type,title,target_id:target,created_at:Date.now(),read_at:null});updateNotificationBadges();}
async function mutate(path,body){if(!S.demo){await api(projectPath()+path,body);await refresh();return;}if(path==='/requests'){S.data.requests.unshift({id:crypto.randomUUID(),version_id:body.versionId,start:body.start,end:body.end,text:body.text,status:'open',created_at:Date.now()});addDemoNotice('request','새 수정 요청이 도착했어요.',S.data.requests[0].id);}else if(path.startsWith('/requests/')){Object.assign(S.data.requests.find(r=>r.id===path.split('/').pop()),{status:body.status,resolved_version_id:body.versionId});addDemoNotice('request','수정 요청 상태가 변경되었어요.',path.split('/').pop());}else if(path==='/messages'){S.data.messages.push({id:crypto.randomUUID(),role:S.user.role,text:body.text,request_id:body.requestId,created_at:Date.now()});addDemoNotice('message','프로젝트에 새 메시지가 도착했어요.',body.requestId||null);}else if(path==='/status')S.data.project.status=body.status;}
function replyModal(id){const r=S.data.requests.find(x=>x.id===id);S.replyTo=id;modal('수정 요청에 답변',`<span class="timestamp">${fmt(r.start)} — ${fmt(r.end)}</span><p style="margin:15px 0">${esc(r.text)}</p><div style="max-height:300px;overflow:auto">${S.data.messages.filter(m=>m.request_id===id).map(messageHTML).join('')}</div>${S.data.project.status==='active'?'<form id="reply-form" style="margin-top:18px"><textarea name="text" required maxlength="2000" placeholder="이 요청에 답변을 남겨 주세요." aria-label="답변"></textarea><button class="primary">답변 보내기</button></form>':''}`);}
function inviteModal(code){modal(S.demo?'초대 코드 미리보기':'고객을 작업실에 초대하기',`<p>고객에게 아래 링크와 접속 코드를 전달해 주세요.<br>고객은 회원가입 없이 이 프로젝트에만 들어올 수 있어요.</p><label style="margin-top:15px">앱 링크<input readonly value="${esc(APP_BASE.href)}" id="invite-link"></label><div class="code" id="invite-code">${esc(code)}</div><button class="primary" data-action="copy-invite">링크와 코드 복사</button><p style="margin-top:15px">접속 코드는 이 창에서만 표시돼요. 재발급하면 이전 코드와 고객의 접속이 종료돼요.</p>`);}
async function enablePush(){if(S.demo)throw Error('데모에서는 기기를 등록하지 않아요. 실제 작업실에서 연결해 주세요.');const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);if(ios&&!(navigator.standalone||matchMedia('(display-mode: standalone)').matches))throw Error('먼저 Safari에서 홈 화면에 추가한 뒤 MIXROOM 아이콘을 열어 주세요.');if(!('serviceWorker'in navigator&&'PushManager'in window&&'Notification'in window))throw Error('이 브라우저에서는 알림을 지원하지 않아요. 설치 가이드를 확인해 주세요.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('알림이 차단되어 있어요. 휴대폰·브라우저 설정에서 허용해 주세요.');if(!S.config.publicKey)throw Error('서버 알림 연결이 준비되지 않았어요. 엔지니어에게 알려 주세요.');const reg=await navigator.serviceWorker.ready,raw=atob(S.config.publicKey.replace(/-/g,'+').replace(/_/g,'/')),key=Uint8Array.from(raw,c=>c.charCodeAt(0));const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api('/subscription',sub.toJSON());toast('이 기기의 알림이 연결되었어요. 테스트 알림을 확인해 보세요.');if(S.view==='settings')renderContent();}
async function disablePush(){if(S.demo)return;const reg=await navigator.serviceWorker?.getRegistration(),sub=await reg?.pushManager.getSubscription();if(sub){await api('/subscription',{endpoint:sub.endpoint},'DELETE');await sub.unsubscribe();}toast('이 기기의 알림 연결을 해제했어요.');}
async function action(name,el){
  if(await guideAction(name,el))return;
  if(name==='close-modal')return closeModal();
  if(name==='auth-role'){S.authRole=el.dataset.role;return renderAuth();}
  if(name==='auth-guide'){return modal('사진으로 보는 설치·알림 가이드',`<div class="guide-modal">${guideHTML('client',true)}</div>`);}
  if(name==='setup'){return modal('엔지니어 계정 만들기','<p style="margin-bottom:18px">서버를 설치한 사람이 받은 초기 설정 코드가 필요해요.</p><form id="setup-form"><label>초기 설정 코드<input name="code" type="password" required autocomplete="off"></label><label>스튜디오 이름<input name="name" required maxlength="40" placeholder="예: 관리자"></label><label>관리자 비밀번호<input name="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" placeholder="12자 이상"></label><p class="error" id="setup-error"></p><button class="primary">계정 만들기</button></form>');}
  if(name==='entry-preview'){audio.close();S.chatDrafts={};S.user=null;return renderAuth();}
  if(name==='demo-role'){S.user.role=S.user.role==='engineer'?'client':'engineer';S.user.name=S.user.role==='engineer'?'관리자':S.data?.project.client_name||'고객';S.user.projectId=S.user.role==='client'?S.data?.project.id:null;if(S.view==='customers'&&S.user.role==='client')S.view='project';S.chatDrafts={};return render();}
  if(name==='view'){if(el.dataset.view!=='project')audio.pause();S.view=el.dataset.view;if(S.view==='projects'&&S.user.role==='client')return openProject(S.data.project.id);if(S.view==='chat'&&(!S.data||S.data.project.status==='archived')){const first=visibleProjects().find(p=>p.status!=='archived');if(first)return openProject(first.id,'chat');}render();if(S.view==='chat')await readCurrentChat();return;}
  if(name==='open-chat')return openProject(el.dataset.id,'chat');
  if(name==='customer-manage')return customerManage(el.dataset.id);
  if(name==='open-project')return openProject(el.dataset.id);
  if(name==='filter'){S.filter=el.dataset.filter;return updateReview();}
  if(name==='play'){if(audio.playing)audio.pause();else await audio.play();return tick(audio.time());}
  if(name==='ab'){audio.select(el.dataset.key);document.querySelectorAll('[data-action="ab"]').forEach(b=>b.classList.toggle('active',b.dataset.key===audio.selected));for(const key of ['A','B'])$('#track-'+key)?.classList.toggle('selected',audio.selected===key);if($('#comment-version'))$('#comment-version').textContent=`듣고 있는 ${audio.selected} 버전에 남겨요.`;return drawWaves();}
  if(name==='loop'){await audio.setLoop(!audio.loop);el.classList.toggle('loop-active',audio.loop);el.setAttribute('aria-pressed',String(audio.loop));return syncRange();}
  if(name==='mark-time'){const t=audio.time();await audio.setRange(t,Math.min(audio.duration(),t+5));return syncRange();}
  if(name==='request-play'){const r=S.data.requests.find(x=>x.id===el.dataset.id);S.a=r.version_id;S.b=r.resolved_version_id||S.data.versions[0].id;$('#version-A').value=S.a;$('#version-B').value=S.b;await loadAudio();if(r.start>=audio.duration()){toast('수정본에 이 구간이 없어 요청 당시 버전으로 재생해요.');S.b=S.a;$('#version-B').value=S.b;await loadAudio();}await audio.setRange(r.start,Math.max(r.start+.1,r.end));await audio.setLoop(true);await audio.seek(r.start);await audio.play();$('[data-action="loop"]').classList.add('loop-active');syncRange();return;}
  if(name==='reply')return replyModal(el.dataset.id);
  if(name==='confirm-request'||name==='reopen-request'){await mutate('/requests/'+el.dataset.id,{status:name==='confirm-request'?'confirmed':'open'});updateReview();return toast(name==='confirm-request'?'수정 확인을 전달했어요.':'다시 확인을 요청했어요.');}
  if(name==='new-project'){return modal('새 프로젝트','<form id="project-form"><label>프로젝트 이름<input name="title" required maxlength="100" placeholder="프로젝트 제목"></label><label>고객 표시 이름<input name="client" required maxlength="60" placeholder="고객 이름"></label><label>프로젝트 설명<textarea name="description" maxlength="1000" placeholder="장르, 작업 범위, 일정 등을 적어 주세요."></textarea></label><button class="primary">프로젝트 만들고 초대키 받기</button></form>');}
  if(name==='invite'){return modal('접속 코드 재발급','<p>기존 고객 접속과 알림 연결이 종료돼요. 새 코드를 고객에게 전달해 주세요.</p><button class="primary" data-action="regenerate-invite" style="margin-top:20px">새 접속 코드 발급</button>');}
  if(name==='regenerate-invite'){const r=S.demo?{code:'demo-2026-mixroom-preview'}:await api(projectPath()+'/invite',{});return inviteModal(r.code);}
  if(name==='copy-invite'){await navigator.clipboard.writeText(`MIXROOM 작업실\n${$('#invite-link').value}\n접속 코드: ${$('#invite-code').textContent}\n홈 화면에 추가하고 알림을 켜면 새 수정본을 바로 확인할 수 있어요.`);return toast('초대 내용을 복사했어요.');}
  if(name==='upload'){return modal('새 버전 업로드','<form id="upload-form"><label>음원 파일<input name="audio" type="file" required accept=".wav,.mp3,.m4a,.aac,.ogg,.flac"></label><p>최대 200MB · WAV, MP3, M4A, AAC, OGG, FLAC<br>원본 그대로 저장 · 변환·압축 없음<br>가능하면 버전마다 같은 시작 위치로 내보내 주세요.</p><label>버전 이름<input name="label" required maxlength="60" placeholder="예: 3차 수정본"></label><label>이번 수정 내용<textarea name="note" maxlength="1000" placeholder="어떤 부분이 바뀌었나요?"></textarea></label><div class="progress"><div id="upload-progress" style="width:0"></div></div><p id="upload-status" role="status"></p><button class="primary">업로드하고 고객에게 알리기</button></form>');}
  if(name==='delete-audio'){const v=S.data.versions.find(v=>v.id===el.dataset.id);return modal('음원 삭제',`<p>v${v.number} · ${esc(v.label)}</p><p>원본 파일을 삭제하고 저장공간을 확보해요. 수정 요청과 답변 기록은 남아요.</p><button class="danger" data-action="confirm-delete-audio" data-id="${v.id}">음원 삭제</button>`);}
  if(name==='confirm-delete-audio'){audio.close();audioGeneration++;buffers.delete(el.dataset.id);if(S.demo){S.data.versions=S.data.versions.filter(v=>v.id!==el.dataset.id);S.data.requests.forEach(r=>{if(r.resolved_version_id===el.dataset.id){r.resolved_version_id=null;r.status='open';}});}else{await api(projectPath()+'/versions/'+el.dataset.id,{},'DELETE');await refresh();}S.a=S.data.versions[1]?.id||S.data.versions[0]?.id;S.b=S.data.versions[0]?.id;closeModal();render();return toast('음원을 삭제했어요.');}
  if(name==='download'){if(S.demo)return toast('데모 음원은 앱에서 합성한 예시예요. 실제 프로젝트에서 다운로드할 수 있어요.');const v=S.data.versions.find(v=>v.id===el.dataset.id);el.disabled=true;try{toast('원본 파일을 준비하고 있어요.');const file=await audioFile(projectPath()+'/versions/'+v.id+'/audio?download=1',v.bytes);const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=v.file_name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);toast('검증한 원본 파일을 다운로드해요.');}finally{el.disabled=false;}return;}
  if(name==='enable-push')return enablePush();
  if(name==='disable-push')return disablePush();
  if(name==='test-push'){if(S.demo)return toast('실제 작업실에서 알림을 연결한 뒤 테스트해 주세요.');if(!S.data)throw Error('프로젝트를 먼저 선택해 주세요.');await api('/push-test',{projectId:S.data.project.id});return toast('테스트 알림을 요청했어요. 알림센터를 확인해 주세요.');}
  if(name==='read-notifications')return readNotifications({all:true});
  if(name==='notification')return openNotification(el.dataset.id);
  if(name==='project-status'){await mutate('/status',{status:S.data.project.status==='active'?'completed':'active'});closeModal();return render();}
  if(name==='close-project'){return modal('고객 접속 종료·정보 삭제',`<p>고객 정보, 모든 음원, 접속 코드, 알림 연결, 수정 요청과 대화를 함께 삭제해요. 되돌릴 수 없어요. 고객이 최종본을 받았는지 먼저 확인해 주세요.</p><form id="close-form" style="margin-top:18px"><label>확인하려면 ‘${esc(S.data.project.title)}’ 입력<input name="confirm" required autocomplete="off"></label><button class="danger">접속 종료하고 삭제</button></form>`);}
  if(name==='logout'){audio.close();if(S.demo){location.href=APP_BASE.href;return;}await disablePush();await api('/logout',{});saveSession(null);stopRealtime();buffers.clear();S.user=null;S.data=null;S.projects=[];S.notifications=[];S.chatDrafts={};return renderAuth();}
}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;try{await action(el.dataset.action,el);}catch(error){toast(error.message);if($('#push-result')&&el.dataset.action?.includes('push'))$('#push-result').textContent=error.message;}});
document.addEventListener('change',async e=>{try{if(e.target.id==='version-A'||e.target.id==='version-B'){S[e.target.id.endsWith('A')?'a':'b']=e.target.value;await loadAudio();}else if(['range-start','range-end'].includes(e.target.id)){let start=Number($('#range-start').value),end=Number($('#range-end').value);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start||start<0||end>audio.duration()){syncRange();throw Error('음원 안의 시작·끝 시간을 입력해 주세요.');}await audio.setRange(start,end);syncRange();}else if(e.target.id==='offset'){const value=Number(e.target.value);if(!Number.isFinite(value)||Math.abs(value)>10)throw Error('시간 보정은 -10초부터 10초까지 가능해요.');await audio.setOffset(value);syncRange();}else if(e.target.dataset.request){const rid=e.target.dataset.request,status=e.target.value;if(status==='resolved'){modal('어느 버전에 반영했나요?',`<form id="resolve-form" data-id="${rid}"><label>반영 버전<select name="versionId">${options(S.b)}</select></label><button class="primary">반영 완료하고 고객에게 알리기</button></form>`);}else if(status){await mutate('/requests/'+rid,{status});updateReview();}}}catch(error){toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='volume')audio.setVolume(Number(e.target.value));if(e.target.id==='chat-message'&&S.data)S.chatDrafts[S.data.project.id]=e.target.value;});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,b=Object.fromEntries(new FormData(f)),button=f.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;try{
  if(f.id==='login-form'){if(S.demo){S.data=S.demoRooms['demo-project'];if(S.authRole==='client'&&S.data.project.status==='archived')throw Error('접속 코드가 만료되었어요. 새로고침하면 미리보기가 초기화됩니다.');S.user={role:S.authRole,name:S.authRole==='engineer'?'관리자':S.data.project.client_name,projectId:S.authRole==='client'?'demo-project':null};S.view=S.authRole==='engineer'?'customers':'project';render();}else{await api('/login',{...b,role:S.authRole});await boot();}}
  else if(f.id==='setup-form'){await api('/setup',b);closeModal();await boot();}
  else if(f.id==='project-form'){if(S.demo){const p={id:crypto.randomUUID(),title:b.title,client_name:b.client,description:b.description,status:'active',created_at:Date.now(),updated_at:Date.now()};S.projects.push(p);S.demoRooms[p.id]={project:p,versions:[],requests:[],messages:[]};await openProject(p.id);inviteModal('DEMO-'+p.id.slice(0,8).toUpperCase());}else{const p=await api('/projects',b);await refresh();await openProject(p.id);inviteModal(p.code);}}
  else if(f.id==='request-form'){const offset=audio.selected==='B'?audio.offset:0,versionId=audio.selected==='A'?S.a:S.b;await mutate('/requests',{versionId,start:Math.max(0,audio.range.start+offset),end:Math.max(0,audio.range.end+offset),text:b.text});f.reset();updateReview();toast('수정 요청을 남겼어요.');}
  else if(f.id==='chat-form'||f.id==='reply-form'){await mutate('/messages',{text:b.text,requestId:f.id==='reply-form'?S.replyTo:null});f.reset();if(f.id==='reply-form')replyModal(S.replyTo);else{S.chatDrafts[S.data.project.id]='';if($('#chat-message'))$('#chat-message').value='';updateChat(true);}toast('메시지를 보냈어요.');}
  else if(f.id==='resolve-form'){await mutate('/requests/'+f.dataset.id,{status:'resolved',versionId:b.versionId});closeModal();updateReview();}
  else if(f.id==='upload-form'){await uploadAudio(f,b);}
  else if(f.id==='close-form'){if(S.demo){if(b.confirm!==S.data.project.title)throw Error('프로젝트 이름을 정확히 입력해 주세요.');S.data.project.status='archived';S.data.project.client_name='';S.data.messages=[];S.data.requests=[];delete S.chatDrafts[S.data.project.id];S.notifications=S.notifications.filter(n=>n.project_id!==S.data.project.id);S.data.versions=[];S.data.project.title='종료된 프로젝트';S.data.project.description='';}else{await api(projectPath()+'/close',{confirm:b.confirm});await refresh();}closeModal();render();toast('고객 접속을 종료하고 정보를 삭제했어요.');}
}catch(error){if(f.id==='login-form')$('#auth-error').textContent=error.message;else if(f.id==='setup-form')$('#setup-error').textContent=error.message;else toast(error.message);}finally{if(button)button.disabled=false;}});
async function uploadAudio(form,b){if(S.demo)throw Error('음원 업로드는 실제 작업실에서 사용할 수 있어요.');const file=b.audio;if(!file?.size||file.size>200*1024*1024)throw Error('200MB 이하 음원을 선택해 주세요.');const status=$('#upload-status');status.textContent='음원 길이를 확인하고 있어요…';const url=URL.createObjectURL(file),media=new Audio();const duration=await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('이 브라우저에서 읽을 수 없는 음원이에요. WAV 또는 MP3로 다시 시도해 주세요.')),20000);media.onloadedmetadata=()=>{clearTimeout(timeout);resolve(media.duration);};media.onerror=()=>{clearTimeout(timeout);reject(Error('음원을 읽을 수 없어요. WAV 또는 MP3로 다시 시도해 주세요.'));};media.src=url;}).finally(()=>{URL.revokeObjectURL(url);media.src='';});if(!Number.isFinite(duration)||duration<=0)throw Error('음원 길이를 확인할 수 없어요.');const p=projectPath(),u=await api(p+'/uploads',{fileName:file.name,bytes:file.size,duration,label:b.label,note:b.note});let completed=false;try{const parts=[];for(let start=0;start<file.size;start+=u.chunkSize){const bytes=await file.slice(start,Math.min(file.size,start+u.chunkSize)).arrayBuffer(),hash=await checksum(bytes),partNumber=parts.length+1,r=await apiFetch(p+'/uploads/'+u.id+'/'+partNumber,{method:'PUT',headers:{'X-Content-SHA256':hash},body:bytes});const part=await r.json();if(!r.ok)throw Error(part.error||'업로드에 실패했어요.');if(part.etag!==hash)throw Error('파일 검증에 실패했어요. 다시 업로드해 주세요.');parts.push(part);const percent=Math.round(Math.min(file.size,start+u.chunkSize)/file.size*100);$('#upload-progress').style.width=percent+'%';status.textContent=`${percent}% 업로드 중 · 창을 닫지 말아 주세요.`;}await api(p+'/uploads/'+u.id+'/complete',{parts});completed=true;closeModal();await refresh();S.a=S.data.versions[1]?.id||S.data.versions[0].id;S.b=S.data.versions[0].id;S.view='project';render();toast('새 버전을 올리고 고객에게 알림을 남겼어요.');}finally{if(!completed){await api(p+'/uploads/'+u.id,{},'DELETE').catch(()=>{});}}}
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['INPUT','TEXTAREA','SELECT','BUTTON'].includes(document.activeElement.tagName)&&!$('#modal').open&&S.view==='project'&&S.audioReady){e.preventDefault();action('play',null);}if(e.key==='Escape')S.replyTo=null;});
document.addEventListener('mixroom-theme-change',drawWaves);window.addEventListener('resize',drawWaves);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh().catch(()=>{});});
async function boot(){clearInterval(pollTimer);stopRealtime();if(S.demo){demoData();const screen=new URLSearchParams(location.search).get('screen');if(['project','customers','chat'].includes(screen)){S.user={role:screen==='project'?'client':'engineer',name:screen==='project'?'고객 01':'관리자',projectId:screen==='project'?'demo-project':null};S.view=screen;render();if(screen==='chat')await readCurrentChat();}else{S.user=null;renderAuth();}return;}try{S.config=await api('/config');try{S.user=await api('/me');S.data=null;}catch{renderAuth();return;}await refresh();const id=new URLSearchParams(location.search).get('project')||S.user.projectId||S.projects.find(p=>p.status!=='archived')?.id;if(id)await openProject(id,new URLSearchParams(location.search).get('view')==='chat'?'chat':S.user.role==='engineer'&&!new URLSearchParams(location.search).has('project')?'customers':'project');else{S.view=S.user.role==='engineer'?'customers':'projects';render();}const notificationId=new URLSearchParams(location.search).get('notification');if(notificationId){try{await openNotification(notificationId);}catch(e){toast(e.message);}const cleanURL=new URL(location.href);cleanURL.searchParams.delete('notification');history.replaceState(null,'',cleanURL);}startRealtime(api,()=>{if(S.user&&!document.hidden&&!$('#modal').open)refresh().catch(()=>{});});pollTimer=setInterval(()=>{if(!document.hidden&&!$('#modal').open)refresh().catch(()=>{});},30000);}catch(e){renderAuth('서버 연결을 확인해 주세요. '+e.message);}}
if('serviceWorker'in navigator)navigator.serviceWorker.register(new URL('sw.js',APP_BASE),{scope:APP_BASE.pathname}).catch(()=>{});
boot();
